import {describe, expect, it} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry accepted input', () => {
  it('passes accepted weather input through unchanged (specs/hal-engine-tool-input-validation/spec.md#3)', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather forecast',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => JSON.stringify(input)
    );

    const input = {location: 'Berlin', extra: 'retained'};
    const response = await registry.execute('weather', input);

    expect(JSON.parse(response.result)).toEqual(input);
  });
});
EOF
